function renderNutritionAdvice(o,e,n){if(!o||"string"!=typeof o.bodyTemplate)return{body:null,blockReason:"template_missing"};if(!Array.isArray(e)||0===e.length)return{body:null,blockReason:"no_food_to_render"};var l=e.map(function(o){return o.label}).join(", "),r=o.bodyTemplate,a=o.allowedVariables||[];if(-1!==r.indexOf("{{flagged_foods}}")){if(-1===a.indexOf("flagged_foods")||!Array.isArray(n)||0===n.length)return{body:null,blockReason:"flagged_foods_unavailable"};r=r.split("{{flagged_foods}}").join(n.join(", "))}return{body:r=r.split("{{foods}}").join(l),blockReason:null}}